AND p.image_usable = 1

AND p.source_domain IN #{v}
AND p.custom_category IN #{v}
AND p.product_role IN #{v}
AND p.categories LIKE #{v} ESCAPE '!'
AND p.name LIKE #{f.namePattern} ESCAPE '!'
AND p.sku LIKE #{f.skuPattern} ESCAPE '!'
AND p.language = #{f.language}
AND p.regular_price >= #{f.minPrice}
AND p.regular_price <= #{f.maxPrice}
AND p.created_at >= #{f.startDate}
AND p.created_at < #{f.endExclusive}

mapper.select:
SELECT /*+ MAX_EXECUTION_TIME(18000) */ p.id,p.sku,p.name,p.regular_price,p.categories,p.custom_category,
  p.product_role,p.source_domain,p.language,p.images,p.created_at
FROM scraped_data.ecommerce_products p WHERE p.id <= #{snapshot}
AND p.id < #{before}
 ORDER BY p.id DESC LIMIT #{limit}

SELECT /*+ MAX_EXECUTION_TIME(25000) */ p.id,p.sku,p.name,p.description,p.regular_price,p.categories,
  p.images,p.cf_opingts,p.custom_category,p.product_role,p.source_domain,p.language
FROM scraped_data.ecommerce_products p WHERE p.id > #{after} AND p.id <= #{snapshot}
 ORDER BY p.id ASC LIMIT #{limit}
